        array('/', '首页', $path === '/'),
        array('/products', 'VPN 订阅', strpos($path, '/products') === 0),
        array('/accounts', '海外账号', strpos($path, '/accounts') === 0),
        array('/benefits', '每日公益节点', $path === '/benefits'),
        array('/downloads', '软件下载', $path === '/downloads'),
        array('/articles', '使用教程', strpos($path, '/articles') === 0),
    );
