$router->get('/register', function() use($config){$ref=isset($_GET['ref'])?trim($_GET['ref']):'';$body='<div class="auth-layout"><section class="auth-card"><span class="auth-eyebrow">开始使用</span><h1>创建账户</h1><p>使用邮箱创建账户，管理订阅、账号商品与交付进度。</p><form method="post">'.csrf_field().'<input type="hidden" name="ref" value="'.e($ref).'"/><label>邮箱<input type="email" name="email" autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false" placeholder="请输入邮箱地址" required></label><label>昵称（选填）<input name="display_name" maxlength="100" autocomplete="nickname" placeholder="怎么称呼你"></label><label>密码<input type="password" name="password" minlength="8" autocomplete="new-password" placeholder="至少 8 位字符" required></label><button class="button">创建账户　→</button></form><p class="auth-switch">已有账户？<a href="/login">立即登录</a></p></section><aside class="auth-side"><span>'.e($config['app']['name']).'</span><h2>连接世界，<br>从这里开始。</h2><p>选择合适的方案，按步骤完成订阅。</p><div class="auth-orbit" aria-hidden="true">✦</div></aside></div>';page('注册',$body,$config);});
$router->post('/register', function() use($config,$pdo){post_csrf();$email=trim($_POST['email']);$pass=$_POST['password'];$ref=trim(isset($_POST['ref'])?$_POST['ref']:'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){flash('error','请输入有效邮箱和至少 8 位密码。');return redirect('/register');}$s=$pdo->prepare('INSERT INTO users(email,password_hash,display_name,created_at,updated_at) VALUES(?,?,?,?,?)');try{$now=date('Y-m-d H:i:s');$s->execute(array($email,password_hash($pass,PASSWORD_DEFAULT),substr(trim($_POST['display_name']),0,100),$now,$now));$uid=(int)$pdo->lastInsertId();if($ref!=='')(new ActivityService($pdo))->bindReferral($uid,$ref);flash('success','注册成功，请登录。');redirect('/login');}catch(PDOException $e){flash('error','注册失败，邮箱可能已存在。');redirect('/register');}});
$router->get('/login', function() use($config){$body='<div class="auth-layout"><section class="auth-card"><span class="auth-eyebrow">欢迎回来</span><h1>登录账户</h1><p>登录后管理订单、查看交付内容和售后工单。</p><form method="post">'.csrf_field().'<label>邮箱<input type="email" name="email" autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false" placeholder="请输入邮箱地址" required></label><label>密码<input type="password" name="password" autocomplete="current-password" placeholder="请输入密码" required></label><button class="button">登录账户　→</button></form><p class="auth-switch"><a href="/password/forgot">忘记密码？</a>　还没有账户？<a href="/register">立即注册</a></p></section><aside class="auth-side"><span>'.e($config['app']['name']).'</span><h2>轻松连接，<br>自在探索。</h2><p>一个账户，管理订阅、订单与服务支持。</p><div class="auth-orbit" aria-hidden="true">✦</div></aside></div>';page('登录',$body,$config);});
$router->get('/password/forgot', function() use($config){$body='<div class="auth-flow-card"><h1>找回密码</h1><p>输入注册邮箱，如账号存在，我们会发送重置链接。</p><form method="post" action="/password/forgot">'.csrf_field().'<label>邮箱<input type="email" name="email" autocomplete="email" required></label><button class="button">发送重置链接</button></form></div>';page('找回密码',$body,$config);});
$router->post('/password/forgot', function() use($config,$pdo){post_csrf();header('Cache-Control: no-store');$email=strtolower(trim(isset($_POST['email'])?(string)$_POST['email']:''));$ip=substr(isset($_SERVER['REMOTE_ADDR'])?(string)$_SERVER['REMOTE_ADDR']:'',0,45);$limited=false;$q=$pdo->prepare('SELECT COUNT(*) FROM password_reset_tokens WHERE request_ip=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)');$q->execute(array($ip));$limited=(int)$q->fetchColumn()>=10;if(!$limited&&filter_var($email,FILTER_VALIDATE_EMAIL)){$s=$pdo->prepare('SELECT id,email FROM users WHERE email=? AND status="active"');$s->execute(array($email));$u=$s->fetch();if($u){$q=$pdo->prepare('SELECT COUNT(*) FROM password_reset_tokens WHERE user_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)');$q->execute(array($u['id']));if((int)$q->fetchColumn()<3){$raw=bin2hex(random_bytes(32));$hash=hash('sha256',$raw);$now=date('Y-m-d H:i:s');$pdo->prepare('UPDATE password_reset_tokens SET used_at=? WHERE user_id=? AND used_at IS NULL')->execute(array($now,$u['id']));$pdo->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at,request_ip,created_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE),?,?)')->execute(array($u['id'],$hash,$ip,$now));$base=rtrim((string)$config['app']['base_url'],'/');$link=$base.'/password/reset?token='.rawurlencode($raw);(new NotificationOutboxService($pdo))->enqueue('password_reset','password_reset:'.$hash,array('to'=>$u['email'],'subject'=>'密码重置链接','body'=>'我们收到了密码重置请求。请在 30 分钟内打开以下链接设置新密码：\n'.$link.'\n如果不是你本人操作，请忽略此邮件。','expires_minutes'=>30),'email');}}}flash('success','如该邮箱对应有效账户，我们将发送密码重置说明。');redirect('/password/forgot');});
$router->get('/password/reset', function() use($config){$token=isset($_GET['token'])?(string)$_GET['token']:'';$body='<div class="auth-flow-card"><h1>设置新密码</h1><p>请输入并确认你的新密码。</p><form method="post" action="/password/reset">'.csrf_field().'<input type="hidden" name="token" value="'.e($token).'"><label>新密码<input type="password" name="password" minlength="8" autocomplete="new-password" required></label><label>确认新密码<input type="password" name="password_confirm" minlength="8" autocomplete="new-password" required></label><button class="button">重置密码</button></form></div>';page('重置密码',$body,$config);});
$router->post('/password/reset', function() use($config,$pdo){post_csrf();header('Cache-Control: no-store');$token=isset($_POST['token'])?(string)$_POST['token']:'';$password=isset($_POST['password'])?(string)$_POST['password']:'';$confirm=isset($_POST['password_confirm'])?(string)$_POST['password_confirm']:'';if(strlen($password)<8||strlen($password)>4096||!hash_equals($password,$confirm)){flash('error','密码至少 8 位，且两次输入必须一致。');return redirect('/password/reset?token='.rawurlencode($token));}try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE');$s->execute(array(hash('sha256',$token)));$row=$s->fetch();if(!$row)throw new RuntimeException('invalid');$now=date('Y-m-d H:i:s');$u=$pdo->prepare('UPDATE users SET password_hash=?,password_changed_at=?,updated_at=? WHERE id=?');$u->execute(array(password_hash($password,PASSWORD_DEFAULT),$now,$now,$row['user_id']));$pdo->prepare('UPDATE password_reset_tokens SET used_at=? WHERE user_id=? AND used_at IS NULL')->execute(array($now,$row['user_id']));$pdo->commit();$_SESSION=array();session_destroy();flash('success','密码已重置，请使用新密码登录。');redirect('/login');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','重置链接无效或已过期，请重新申请。');redirect('/password/forgot');}});
$router->post('/login', function() use($config,$pdo){post_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE email=? AND status="active"');$s->execute(array(trim($_POST['email'])));$u=$s->fetch();if(!$u||!password_verify($_POST['password'],$u['password_hash'])){flash('error','邮箱或密码错误。');return redirect('/login');}session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['display_name']?:$u['email'];$_SESSION['user_password_changed_at']=isset($u['password_changed_at'])?(string)$u['password_changed_at']:'';redirect('/orders');});
$router->post('/logout', function(){post_csrf();$_SESSION=array();session_destroy();redirect('/');});
$router->get('/order-confirm', function() use($config,$pdo){$uid=Security::requireUser();$productId=isset($_GET['product_id'])?(int)$_GET['product_id']:0;$planId=isset($_GET['plan_id'])?(int)$_GET['plan_id']:0;$groupId=isset($_GET['group_id'])?(int)$_GET['group_id']:0;$s=$pdo->prepare('SELECT p.*,pp.id plan_id,pp.name plan_name,pp.duration_days plan_days,pp.price_cents plan_price FROM products p JOIN product_plans pp ON pp.product_id=p.id WHERE p.id=? AND pp.id=? AND p.status="active" AND pp.status="active"');$s->execute(array($productId,$planId));$row=$s->fetch();if(!$row)return page('方案不可用','<div class="empty">套餐或期限方案不存在、已下架。</div>',$config);$isAccount=catalog_type($row)==='account';if($isAccount && ($groupId || !empty($_GET['promotion_code']) || (isset($_GET['quantity'])&&(string)$_GET['quantity']!=='1'))){http_response_code(400);return page('不支持活动','<div class="empty">账号商品不参与优惠或拼团。</div>',$config);}$promotion='';if($groupId){$s=$pdo->prepare('SELECT 1 FROM group_members gm JOIN group_campaign_plans gp ON gp.campaign_id=gm.campaign_id AND gp.product_plan_id=? JOIN group_campaigns gc ON gc.id=gm.campaign_id WHERE gm.campaign_id=? AND gm.user_id=? AND gm.status="pending" AND gc.status="forming" AND (gc.expires_at IS NULL OR gc.expires_at>=NOW())');$s->execute(array($planId,$groupId,$uid));if(!$s->fetch())return page('拼团方案不可用','<div class="empty">你不是该拼团待付款成员，或所选方案不适用于此拼团。</div>',$config);$promotion='group:'.$groupId;}$body='<div class="checkout-page"><a class="checkout-back" href="/products">← 返回选购</a><header class="checkout-heading"><h1>确认订单，完成支付</h1><p>请核对所选方案，提交订单后，选择适合你的支付方式。</p></header><section class="checkout-progress"><h2>购买进度</h2><ol class="checkout-steps" aria-label="购买进度"><li><span>1</span><img src="/assets/progress-check.svg" alt=""><b>选择套餐</b><small>已完成</small></li><li aria-current="step"><span>2</span><img src="/assets/progress-wallet.svg" alt=""><b>确认订单</b><small>当前步骤</small></li><li><span>3</span><img src="/assets/progress-key.svg" alt=""><b>付款与交付</b><small>订单创建后</small></li></ol></section><form class="checkout-layout" method="post" action="/orders">'.csrf_field().'<input type="hidden" name="product_id" value="'.(int)$row['id'].'"><input type="hidden" name="plan_id" value="'.(int)$row['plan_id'].'"><div class="checkout-main"><section class="checkout-card"><div class="checkout-card-head"><h2>套餐与订单信息</h2><a href="/'.($isAccount?'accounts':'products').'/'.(int)$row['id'].'">重新选择</a></div><div class="checkout-product"><span class="checkout-product-icon" aria-hidden="true"><img src="/assets/checkout-layers.svg" alt=""></span><div><h3>'.e($row['name']).'</h3><p>'.e($row['plan_name']).' · '.($isAccount?'单个账号':(int)$row['plan_days'].' 天').'</p><span class="checkout-tag">'.($isAccount?'账号商品':'订阅服务').'</span></div><strong>'.money($row['plan_price']).'</strong></div><dl class="checkout-details"><div><dt>购买数量</dt><dd>1 份</dd></div><div><dt>商品说明</dt><dd class="checkout-description">'.e($row['description']).'</dd></div><div><dt>订单编号</dt><dd>提交订单后生成</dd></div></dl></section>'.($isAccount?'<input type="hidden" name="quantity" value="1">'.account_public_details($row):'<section class="checkout-card"><h2>优惠券</h2>'.($groupId?'<input type="hidden" name="promotion_code" value="'.e($promotion).'"><p class="checkout-help">已参与拼团，优惠将在创建订单时由系统自动计算。</p>':'<label for="checkout-promotion">优惠码 / 优惠券代码（可选）</label><div class="checkout-coupon-input"><img src="/assets/checkout-ticket.svg" alt=""><input id="checkout-promotion" name="promotion_code" maxlength="100" placeholder="请输入优惠码或优惠券代码"></div><p class="checkout-help">优惠有效性与实际抵扣金额将在提交订单时核算。</p>').'</section>').'<section class="checkout-card checkout-note-card"><details><summary>订单备注 <span>选填</span></summary><label for="checkout-note">备注（可选）</label><textarea id="checkout-note" name="note" maxlength="500" placeholder="如有需要说明的事项，请在这里填写"></textarea></details></section><section class="checkout-card checkout-payment-card"><h2>支付方式说明</h2><p class="checkout-help">提交订单后选择支付方式，本页不会发起扣款。</p><div class="checkout-payment-options"><div class="checkout-payment-info"><img src="/assets/checkout-wallet.svg" alt=""><div><b>在线支付</b><span>以订单详情的可用渠道为准</span></div></div><div class="checkout-payment-info"><img src="/assets/checkout-scan.svg" alt=""><div><b>消费余额</b><span>余额足够时可全额支付</span></div></div></div></section></div><aside class="checkout-sidebar"><section class="checkout-card checkout-total"><h2>金额明细</h2><div class="checkout-summary-status"><span>待提交</span><small>核对方案后创建订单</small></div><dl><div><dt>商品金额</dt><dd>'.money($row['plan_price']).'</dd></div><div><dt>购买数量</dt><dd>× 1</dd></div><div><dt>优惠抵扣</dt><dd>提交后核算</dd></div></dl><div class="checkout-total-amount"><span>优惠前金额</span><strong>'.money($row['plan_price']).'</strong></div><p class="checkout-help">最终应付金额以创建后的订单为准；全额优惠订单自动完成零元结算。</p><button class="button" type="submit"><img src="/assets/checkout-lock.svg" alt="">提交订单，前往支付</button><a class="checkout-continue" href="/products">继续选购</a></section><section class="checkout-safe"><img src="/assets/checkout-info.svg" alt=""><div><b>安全支付提醒</b><p>请在订单创建后确认实际金额，通过订单详情完成付款，勿向陌生账户转账。</p></div></section><p class="checkout-footnote">提交订单不会立即扣款，请勿重复下单。</p></aside><div class="purchase-mobile-action"><div><strong>'.money($row['plan_price']).'</strong><small>优惠前金额 · 提交后核算</small></div><button type="submit"><img src="/assets/purchase-arrow.svg" alt="">提交订单</button></div></form></div>';page('确认订单',$body,$config);});
$router->post('/orders', function() use($config,$pdo){$uid=Security::requireUser();post_csrf();try{$no=(new OrderService($pdo))->create($uid,(int)$_POST['product_id'],(int)$_POST['plan_id'],trim($_POST['note']),trim(isset($_POST['promotion_code'])?$_POST['promotion_code']:''),isset($_POST['quantity'])?$_POST['quantity']:1);flash('success','订单已创建，请选择支付方式或等待人工确认。');redirect('/orders/'.$no);}catch(Exception $e){flash('error',$e->getMessage());redirect('/products');}});
$router->post('/payment/start/{no}/{type}', function($no,$type) use($config,$pdo){$uid=Security::requireUser();post_csrf();try{$payment=(new PaymentService($pdo,$config))->createPayment($no,$uid,$type);if($payment['url']!=='')redirect($payment['url']);if($payment['urlscheme']!=='')redirect($payment['urlscheme']);$body='<div class="form-card"><h1>请使用客户端完成支付</h1><p>订单 '.e($no).' 的二维码内容：</p><code>'.e($payment['qrcode']).'</code><p><a href="/orders/'.e($no).'">返回订单</a></p></div>';page('等待支付',$body,$config);}catch(Exception $e){flash('error',$e->getMessage());redirect('/orders/'.$no);}});
$router->get('/payment/return', function() use($config,$pdo){$gatewayNo=isset($_GET['payment_order'])?preg_replace('/[^A-Za-z0-9_-]/','',$_GET['payment_order']):'';$no='';if($gatewayNo!==''){$s=$pdo->prepare('SELECT o.order_no FROM orders o JOIN payment_records p ON p.order_id=o.id AND p.gateway_order_no=? LIMIT 1');$s->execute(array($gatewayNo));$no=(string)$s->fetchColumn();}if($no==='')$no=isset($_GET['order_no'])?preg_replace('/[^A-Za-z0-9_-]/','',$_GET['order_no']):'';if($no!=='')flash('success','已返回支付页面，最终结果以异步通知为准。');redirect($no!==''?'/orders/'.$no.'/payment-result':'/orders');});
