$router->get('/orders/{no}/payment-result', function($no) use($config,$pdo){
    $uid=Security::requireUser();
    header('Cache-Control: no-store, private');
    header('Referrer-Policy: no-referrer');
    $o=(new OrderService($pdo))->getForUser($no,$uid);
    if(!$o){http_response_code(404);return page('订单不存在','<div class="empty">订单不存在或无权查看。</div>',$config);}
    if(!in_array($o['status'],array('paid_waiting_group','pending_delivery','delivered'),true))return redirect('/orders/'.rawurlencode($no));
    $isAccount=catalog_type($o,true)==='account';
    $delivered=$o['status']==='delivered';
    $detailUrl='/orders/'.rawurlencode($no).'?view=detail';
    $title=$delivered?'订单已完成，交付内容已准备好':($o['status']==='paid_waiting_group'?'付款已确认，等待成团':'付款已确认，等待交付');
    $subtitle=$delivered?'请妥善保存交付信息，你可以随时在订单详情中再次查看。':($o['status']==='paid_waiting_group'?'成团后将进入交付流程，最新进度以订单详情为准。':'管理员正在准备交付，请在订单详情关注最新进度。');
    $delivery='<div class="result-waiting"><h3>交付准备中</h3><p>'.e($subtitle).'</p><a class="result-outline" href="'.e($detailUrl).'">查看订单进度</a></div>';
    if($delivered){
        $s=$pdo->prepare('SELECT * FROM delivery_records WHERE order_id=? AND is_current=1');$s->execute(array($o['id']));$d=$s->fetch();
        if($d){
            $crypto=new CryptoService($config);
            $x=json_decode($crypto->decrypt($d['content_ciphertext'],$d['content_nonce'],$d['content_tag']),true);
            $secret=$isAccount?$x['account']:$x['subscription'];
            $content=$isAccount?account_delivery_display($x):'<div class="result-vpn-delivery"><p><b>订阅链接</b></p><code>'.e($x['subscription']).'</code><p><b>账号信息</b><br>'.nl2br(e($x['account'])).'</p><p><b>开通时间：</b>'.e($x['opened_at']).'<br><b>到期时间：</b>'.e($x['expires_at']).'</p><p><b>使用说明</b><br>'.nl2br(e($x['instructions'])).'</p></div>';
            $delivery='<div class="result-secret-box"><small>仅本人可见 · 请勿截图或转发</small><p class="result-masked" aria-label="交付信息已遮罩">•••• — •••• — ••••</p><div class="result-secret-controls"><details class="result-reveal"><summary><img src="/assets/result-eye.svg" alt="">查看交付内容</summary><div class="result-secret-content">'.$content.'</div></details><button type="button" class="result-copy" data-result-copy><img src="/assets/result-copy.svg" alt="">复制'.($isAccount?'账号内容':'订阅链接').'</button><span id="result-copy-value" hidden>'.e($secret).'</span><span class="result-copy-status" role="status" aria-live="polite"></span></div></div>';
        }else{$title='付款已确认，请核对交付记录';$subtitle='当前未找到可展示的交付内容，请查看订单详情或联系支持。';}
    }
