s="delivery"><h2>交付内容</h2><p class="subscription-row"><b>订阅链接：</b><span class="subscription-value"><code id="subscription-link">'.e($x['subscription']).'</code><button type="button" class="copy-subscription" data-copy-target="subscription-link">复制</button></span></p><p><b>账号信息：</b>'.nl2br(e($x['account'])).'</p><p><b>开通时间：</b>'.e($x['opened_at']).'　<b>到期时间：</b>'.e($x['expires_at']).'</p><p><b>使用说明：</b>'.nl2br(e($x['instructions'])).'</p></div>';}} $paymentBox='';if($o['status']==='pending_payment'){$ps=(new PaymentService($pdo,$config))->settings();$paymentBox='<section class="order-payment-panel"><div class="order-payment-heading"><div><span class="order-section-label">SECURE CHECKOUT</span><h2>选择支付方式</h2><p>应付金额将以订单实际支付记录为准。</p></div><strong>'.e(money($o['total_amount_cents'])).'</strong></div>';if(!empty($ps['enabled'])){$paymentBox.='<div class="payment-methods">'.(!empty($ps['alipay_enabled'])?'<article class="payment-method-card payment-method-alipay"><span class="payment-method-icon">支</span><div class="payment-method-copy"><b>支付宝支付</b><small>安全快捷，支付成功后自动确认</small></div><form method="post" action="/payment/start/'.e($no).'/alipay">'.csrf_field().'<button class="button" type="submit">立即支付</button></form></article>' : '').(!empty($ps['wechat_enabled'])?'<article class="payment-method-card payment-method-wechat"><span class="payment-method-icon">微</span><div class="payment-method-copy"><b>微信支付</b><small>使用微信完成订单付款</small></div><form method="post" action="/payment/start/'.e($no).'/wxpay">'.csrf_field().'<button class="secondary-button" type="submit">立即支付</button></form></article>':'').'</div>'; } $balance=(new WalletService($pdo))->balance($uid);$canPay=empty($o['payment_started_at'])&&$balance>=(int)$o['total_amount_cents'];$paymentBox.='<div class="payment-method-divider"><span>或使用消费余额</span></div><article class="payment-method-card payment-method-balance"><span class="payment-method-icon">¥</span><div class="payment-method-copy"><b>消费余额</b><small>当前可用 ¥'.e(WalletService::formatAmount($balance)).' · '.(!empty($o['payment_started_at'])?'已发起在线支付，请继续原渠道付款。':($canPay?'余额足够，可全额支付。':'余额不足，请选择其他支付方式。')).'</small></div><form method="post" action="/orders/'.e($no).'/balance-pay">'.csrf_field().'<button class="button" type="submit"'.($canPay?'':' disabled').'>余额支付 '.e(money($o['total_amount_cents'])).'</button></form></article><a class="payment-balance-link" href="/wallet">查看余额明细与流水 →</a><p class="payment-security-note">支付完成后，系统会自动更新订单状态；请勿重复提交不同支付方式。</p></section>';}$statusLabel=status_text($o['status']);$statusClass='order-status-'.e($o['status']);$actions='';if($o['status']==='pending_payment')$actions='<section class="wallet-order-actions"><form method="post" action="/orders/'.e($no).'/cancel">'.csrf_field().'<label>取消原因<input name="reason" maxlength="500" required></label><button class="secondary-button" type="submit">取消未付款订单</button></form></section>';$timeline=(in_array($o['status'],array('paid_waiting_group','pending_delivery','delivered'),true)?'<p><a class="secondary-button" href="/orders/'.e($no).'/payment-result">查看付款与交付结果</a></p>':'').'<section class="order-timeline-card">'.$events.'</section>';if($isAccount&&$delivery)$delivery=str_replace('<div class="delivery account-delivery">','<div class="delivery">',$delivery);$delivery=$delivery?'<section class="order-delivery-card"><div class="order-section-heading"><div><span class="order-section-label">SECURE DELIVERY</span><h2>交付内容</h2></div><span class="delivery-safe">已加密保护</span></div><div class="order-delivery-body">'.$delivery.'</div></section>':'';page('订单详情','<div class="order-detail-page'.($o['status']==='pending_payment'?' order-checkout-state':'').'"><a class="order-back-link" href="/orders">← 返回我的订单</a><div class="order-detail-layout"><div class="order-detail-main"><section class="order-detail-card"><header class="order-detail-header"><div class="order-header-icon">✦</div><div class="order-header-copy"><span class="eyebrow">ORDER / '.e($o['order_no']).'</span><h1>