$workspacePage = function($subscriptions = false) use($config,$pdo) {
    $uid=Security::requireUser();
    $query=$pdo->prepare('SELECT o.id,o.order_no,o.product_name_snapshot,o.plan_name_snapshot,o.duration_days_snapshot,d.opened_at,d.expires_at FROM orders o JOIN delivery_records d ON d.order_id=o.id AND d.is_current=1 WHERE o.user_id=? AND o.product_type_snapshot="vpn" AND o.status="delivered" ORDER BY o.id DESC');
    $query->execute(array($uid));$items=$query->fetchAll();$active=0;$cards='';
    foreach($items as $item){
        $expired=!empty($item['expires_at'])&&strtotime($item['expires_at'])<time();if(!empty($item['expires_at'])&&!$expired)$active++;
        $cards.='<article class="workspace-subscription-card"><div class="workspace-card-heading"><div><span class="workspace-eyebrow">VPN 订阅</span><h2>'.e($item['product_name_snapshot']).'</h2></div><span class="workspace-state'.($expired?' is-expired':'').'">'.($expired?'已到期':'已交付').'</span></div><p>'.e($item['plan_name_snapshot']).' · '.(int)$item['duration_days_snapshot'].' 天</p><dl class="workspace-facts"><div><dt>订单编号</dt><dd>'.e($item['order_no']).'</dd></div><div><dt>开通时间</dt><dd>'.e($item['opened_at']?:'未设置').'</dd></div><div><dt>到期时间</dt><dd>'.e($item['expires_at']?:'未设置').'</dd></div></dl><div class="workspace-subscription-note">订阅地址与使用说明仅在本人订单的交付页面展示，请妥善保管。</div><div class="workspace-card-actions"><a class="button" href="/orders/'.rawurlencode($item['order_no']).'/payment-result">查看订阅交付</a><a class="secondary-button" href="/tickets?order_id='.(int)$item['id'].'#new-ticket">售后工单</a></div></article>';
    }
    if($subscriptions){
        $body='<div class="workspace-content"><header class="ux-page-head"><div><h1>我的订阅</h1><p>查看已交付的 VPN 订阅与有效期，订阅内容以对应订单的实际交付记录为准。</p></div><a class="secondary-button" href="/products">购买新套餐</a></header><div class="workspace-info-strip">共 '.count($items).' 个已交付订阅，其中 '.$active.' 个未到期。未设置到期日期的记录请以交付说明为准。</div><div class="workspace-subscription-grid">'.($cards?:'<section class="service-ui-empty"><h2>还没有已交付订阅</h2><p>付款并完成交付后，你的 VPN 订阅会在这里显示。</p><a class="button" href="/orders">查看我的订单</a></section>').'</div><section class="workspace-help-card"><h2>开始使用你的订阅</h2><p>先安装适用的客户端，再按照交付说明导入订阅。站点不提供节点在线状态或流量统计。</p><div class="workspace-card-actions"><a href="/downloads">下载客户端 →</a><a href="/articles">查看使用教程 →</a></div></section></div>';
        return page('我的订阅',$body,$config);
    }
    $query=$pdo->prepare('SELECT COUNT(*) total,COALESCE(SUM(status="pending_payment"),0) pending,COALESCE(SUM(status IN ("pending_delivery","paid_waiting_group")),0) waiting FROM orders WHERE user_id=?');$query->execute(array($uid));$stats=$query->fetch();
    $query=$pdo->prepare('SELECT order_no,product_name_snapshot,total_amount_cents,status,created_at FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 5');$query->execute(array($uid));$recent='';
