$accountPage=function($section='profile') use($config,$pdo){$uid=Security::requireUser();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute(array($uid));$u=$s->fetch();$displayName=$u['display_name']?:$u['email'];$avatar=e(mb_substr($displayName,0,1,'UTF-8'));$content='';if($section==='profile')$content='<section class="form-card account-profile-card" id="profile"><div class="account-card-head"><div><span class="account-section-kicker">PROFILE</span><h2>基本信息</h2><p>可修改昵称；登录邮箱与注册时间仅供查看。</p></div><span class="account-avatar">'.$avatar.'</span></div><form method="post" action="/account/profile">'.csrf_field().'<label>昵称<input name="display_name" maxlength="100" value="'.e($u['display_name']).'" required></label><label>邮箱<input value="'.e($u['email']).'" disabled></label><label>注册时间<input value="'.e($u['created_at']).'" disabled></label><button class="button">保存更改</button></form></section>';if($section==='security')$content='<section class="form-card account-password-card" id="security"><div class="account-card-head"><div><span class="account-section-kicker">SECURITY</span><h2>账户安全</h2><p>定期更新密码，保护账户信息。</p></div></div><form method="post" action="/account/password">'.csrf_field().'<label>当前密码<input type="password" name="old_password" autocomplete="current-password" placeholder="请输入当前密码" required></label><label>新密码<input type="password" name="new_password" minlength="8" autocomplete="new-password" placeholder="至少 8 位字符" required></label><button class="button">更新密码</button></form><div class="account-security-note"><span>♢</span><p>请使用不易被猜到的密码，并避免与其他网站重复。</p></div></section>';if($section==='notifications'){$n=(new NotificationService($pdo))->recent($uid,5);$notes='';foreach($n as $item)$notes.='<div class="notification-item '.($item['read_at']?'':'unread').'">'.e($item['title']).'<small>'.e($item['created_at']).'</small><p>'.e($item['content']).'</p></div>';$content.='<section class="form-card account-notices-card" id="notifications"><div class="section-head"><div><span class="account-section-kicker">UPDATES</span><h2>最近通知</h2></div><a href="/notifications">查看全部　→</a></div>'.($notes?:'<div class="empty">暂无通知。</div>').'</section>';}$nav='';foreach(array('profile'=>array('/account','◎　基本信息'),'security'=>array('/account/security','♢　账户安全'),'notifications'=>array('/account/notifications','♧　消息通知')) as $key=>$item)$nav.='<a href="'.$item[0].'"'.($section===$key?' class="active" aria-current="page"':'').'>'.$item[1].'</a>';$body='<div class="account-page"><header class="account-page-heading"><div><span class="account-eyebrow">ACCOUNT CENTER</span><h1>账户设置</h1><p>管理你的个人资料与账户安全。</p></div></header><section class="account-identity-card"><span class="account-identity-avatar">'.$avatar.'</span><div class="account-identity-copy"><span>欢迎回来</span><h2>'.e($displayName).'</h2><p>'.e($u['email']).'</p></div><span class="account-member-badge">个人账户</span></section><nav class="account-settings-nav" aria-label="账户设置分类">'.$nav.'</nav><div class="account-settings-content">'.$content.'</div></div>';page('个人中心',$body,$config);};
